import React from "react";
import { ConfirmModalOverlay, ConfirmModalContent, ConfirmModalTitle, ConfirmModalButtons, ConfirmButton } from "./StyledComponents";

const ConfirmDeleteModal = ({ confirmDelete, setDeleteConfirmId }) => (
  <ConfirmModalOverlay onClick={() => setDeleteConfirmId(null)}>
    <ConfirmModalContent onClick={(e) => e.stopPropagation()}>
      <ConfirmModalTitle>Bist du sicher?</ConfirmModalTitle>
      <p>Möchten Sie diesen Platz wirklich löschen?</p>
      <ConfirmModalButtons>
        <ConfirmButton className="yes" onClick={confirmDelete}>JA</ConfirmButton>
        <ConfirmButton className="no" onClick={() => setDeleteConfirmId(null)}>NEIN</ConfirmButton>
      </ConfirmModalButtons>
    </ConfirmModalContent>
  </ConfirmModalOverlay>
);

export default ConfirmDeleteModal;
