import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import {
  Container,
  MainContent,
  PageHeader,
  PageTitle,
  UserInfo,
  UserName,
} from "./StyledComponents";
import SidebarMenu from "./SidebarMenu";
import ProfileSection from "./ProfileSection";
import SpotsSection from "./SpotsSection";
import AddSpotPage from "./AddSpotPage";
import ConfirmDeleteModal from "./ConfirmDeleteModal";
import { BaseUrl } from "../../BaseUrl";

function NursingHomeDashboard() {
  const navigate = useNavigate();

  const [activeSection, setActiveSection] = useState("profile");
  const [userData, setUserData] = useState(null);
  const [spots, setSpots] = useState([]);
  const [showAddPage, setShowAddPage] = useState(false);
  const [deleteConfirmId, setDeleteConfirmId] = useState(null);
  const [userName, setUserName] = useState("Ihr Pflegeheim");
  const [editData, setEditData] = useState({ username: "", email: "", password: "" });
  const [spotToEdit, setSpotToEdit] = useState(null);

  const token = localStorage.getItem("pflegeUserToken");
  const pflegeUserId = localStorage.getItem("pflegeUserId");

  useEffect(() => {
    const isLoggedIn = localStorage.getItem("pflegeLoggedIn");
    if (!isLoggedIn) {
      navigate("/login");
    //  navigate("../login");
      return;
    }

    fetchProfile();
    fetchSpots();
  }, []);

  // ✅ Fetch profile data from API
  const fetchProfile = async () => {
    try {
      const res = await axios.get(`${BaseUrl}get-profile`, {
        params: { user_id: pflegeUserId },
        headers: { Authorization: `Bearer ${token}` },
      });

      if (res.data) {
        setUserData(res.data);
        setUserName(res.data.name);
        setEditData({
          username: res.data.name || "",
          email: res.data.email || "",
          password: "",
        });
      }
    } catch (error) {
      console.error("Profile fetch error:", error.response?.data || error.message);
    }
  };

  // ✅ Fetch all spots from API
  const fetchSpots = async () => {
    try {
      const res = await axios.get(`${BaseUrl}spots`, {
        params: { user_id: pflegeUserId },
        headers: { Authorization: `Bearer ${token}` },
      });

      console.log("Fetched spots:", res.data);
      // setSpots(res.data || []);
      setSpots(res.data.data || []);
    } catch (error) {
      console.error("Error fetching spots:", error.response?.data || error.message);
    }
  };

  // ✅ Delete spot API
  const handleDeleteSpot = (id) => setDeleteConfirmId(id);

  const confirmDelete = async () => {
  try {
    await axios.delete(`${BaseUrl}deletespot/${deleteConfirmId}`, {
      headers: { Authorization: `Bearer ${token}` },
    });

    alert("Spot erfolgreich gelöscht!");
    fetchSpots();
    setDeleteConfirmId(null);
  } catch (error) {
    console.error("Error deleting spot:", error.response?.data || error.message);
    alert("Fehler beim Löschen!");
  }
};


const handleEditSpot = (spot) => {
  // open the AddSpotPage in edit mode
  setSpotToEdit(spot);
  setShowAddPage(true);
};


  // ✅ Logout user
  const handleLogout = () => {
    localStorage.clear();
    navigate("/");
  };

  // ✅ Update profile (if needed)
  const saveProfile = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post(
        `${BaseUrl}update-profile`,
        {
          user_id: pflegeUserId,
          name: editData.username,
          email: editData.email,
          password: editData.password,
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      if (res.data) {
        alert("Profil erfolgreich aktualisiert!");
        fetchProfile();
      }
    } catch (error) {
      console.error("Error updating profile:", error.response?.data || error.message);
      alert("Fehler beim Aktualisieren des Profils!");
    }
  };



  return (
    <Container>
      <SidebarMenu
        userName={userName}
        activeSection={activeSection}
        setActiveSection={setActiveSection}
        handleLogout={handleLogout}
      />

      <MainContent>
        <PageHeader>
          <PageTitle>
            {showAddPage
              ? "Neuen Spot hinzufügen"
              : activeSection === "profile"
              ? "Mein Profil"
              : "Meine Plätze"}
          </PageTitle>
          <UserInfo>
            <UserName>Willkommen, {userName}</UserName>
          </UserInfo>
        </PageHeader>

       {showAddPage ? (
  <AddSpotPage
    setShowAddPage={(val) => {
      setShowAddPage(val);
      if (!val) setSpotToEdit(null); // clear edit state when closing
    }}
    fetchSpots={fetchSpots}
    editData={spotToEdit} // <- pass the spot to edit (null for create)
  />
) : activeSection === "profile" ? (

          <ProfileSection
            userData={userData}
            userName={userName}
            editData={editData}
            setEditData={setEditData}
            saveProfile={saveProfile}
          />
        ) : (
          // <SpotsSection
          //   spots={spots}
          //   setShowAddPage={setShowAddPage}
          //   handleDeleteSpot={handleDeleteSpot}
          // />
          <SpotsSection
          spots={spots}
          setShowAddPage={setShowAddPage}
          handleDeleteSpot={handleDeleteSpot}
          handleEditSpot={handleEditSpot}   // <-- add this
        />

        )}

        {deleteConfirmId && (
          <ConfirmDeleteModal
            confirmDelete={confirmDelete}
            setDeleteConfirmId={setDeleteConfirmId}
          />
        )}
      </MainContent>
    </Container>
  );
}

export default NursingHomeDashboard;
