import React, { useState, useEffect } from 'react';  // <-- ADD useEffect HERE
import { useParams, useNavigate } from 'react-router-dom';
import styled from 'styled-components';

// REST OF THE CODE REMAINS SAME
const Container = styled.div`
  max-width: 600px;
  margin: 2rem auto;
  padding: 2rem;
`;

const FormCard = styled.div`
  background-color: white;
  padding: 2.5rem;
  border-radius: 15px;
  box-shadow: 0 5px 15px rgba(0,0,0,0.1);
`;

const Title = styled.h1`
  color: #2c3e50;
  margin-bottom: 1.5rem;
  text-align: center;
`;

const Form = styled.form`
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
`;

const Label = styled.label`
  margin-bottom: 0.5rem;
  color: #2c3e50;
  font-weight: 500;
`;

const Input = styled.input`
  padding: 0.75rem;
  border: 2px solid rgb(19 20 20);
  border-radius: 8px;
  font-size: 1rem;
  transition: border-color 0.3s;

  &:focus {
    outline: none;
    border-color: #3498db;
  }
`;

const TextArea = styled.textarea`
  padding: 0.75rem;
  border: 2px solid rgb(19 20 20);
  border-radius: 8px;
  font-size: 1rem;
  min-height: 120px;
  resize: vertical;
  transition: border-color 0.3s;

  &:focus {
    outline: none;
    border-color: #3498db;
  }
`;

const Button = styled.button`
  background-color: #3498db;
  color: white;
  padding: 1rem 2rem;
  border: none;
  border-radius: 8px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #2980b9;
  }
`;

const SuccessMessage = styled.div`
  background-color: #d4edda;
  color: #155724;
  padding: 1rem;
  border-radius: 8px;
  margin-bottom: 1.5rem;
  text-align: center;
`;

const BackButton = styled.button`
  background-color: #95a5a6;
  color: white;
  padding: 0.75rem 1.5rem;
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  cursor: pointer;
  transition: background-color 0.3s;

  &:hover {
    background-color: #7f8c8d;
  }
`;

const ButtonGroup = styled.div`
  display: flex;
  gap: 1rem;
  justify-content: center;
`;

function ContactForm() {
  const { id } = useParams();
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    message: ''
  });
  const [submitted, setSubmitted] = useState(false);
  const [facility, setFacility] = useState(null);

  useEffect(() => {
    // Load facility data
    const facilities = JSON.parse(localStorage.getItem('facilities') || '[]');
    const foundFacility = facilities.find(f => f.id === parseInt(id));
    setFacility(foundFacility);

    // Load current user data if logged in
    const isLoggedIn = localStorage.getItem('pflegeLoggedIn');
    if (isLoggedIn) {
      const userEmail = localStorage.getItem('pflegeUserEmail');
      const users = JSON.parse(localStorage.getItem('pflegeUsers') || '[]');
      const currentUser = users.find(u => u.email === userEmail);
      
      if (currentUser) {
        setFormData(prev => ({
          ...prev,
          name: currentUser.name,
          email: currentUser.email,
          phone: currentUser.phone
        }));
      }
    }
  }, [id]);

  const handleInputChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    
    // Store inquiry in localStorage
    const inquiries = JSON.parse(localStorage.getItem('contactInquiries') || '[]');
    const newInquiry = {
      id: Date.now(),
      facility_id: parseInt(id),
      facility_name: facility?.name,
      ...formData,
      created_at: new Date().toISOString(),
      status: 'pending'
    };
    
    inquiries.push(newInquiry);
    localStorage.setItem('contactInquiries', JSON.stringify(inquiries));
    
    setSubmitted(true);
    
    // Redirect after 3 seconds
    setTimeout(() => {
      navigate('/');
    }, 3000);
  };

  const handleGoBack = () => {
    navigate(-1);
  };

  if (!facility) {
    return <div>Lädt...</div>;
  }

  return (
    <Container>
      <FormCard>
        <Title>Kontaktieren Sie uns</Title>
        <p style={{ textAlign: 'center', color: '#7f8c8d', marginBottom: '2rem' }}>
          Sie kontaktieren: <strong>{facility.name}</strong>
        </p>
        
        {submitted && (
          <SuccessMessage>
            Vielen Dank für Ihre Anfrage! Wir haben Ihre Nachricht erfolgreich gesendet. 
            Das Pflegeheim wird sich bald bei Ihnen melden.
          </SuccessMessage>
        )}

        <Form onSubmit={handleSubmit}>
          <FormGroup>
            <Label>Ihr Name *</Label>
            <Input
              type="text"
              name="name"
              value={formData.name}
              onChange={handleInputChange}
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>E-Mail-Adresse *</Label>
            <Input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleInputChange}
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>Telefonnummer</Label>
            <Input
              type="tel"
              name="phone"
              value={formData.phone}
              onChange={handleInputChange}
            />
          </FormGroup>

          <FormGroup>
            <Label>Ihre Nachricht *</Label>
            <TextArea
              name="message"
              value={formData.message}
              onChange={handleInputChange}
              placeholder="Bitte beschreiben Sie Ihr Anliegen..."
              required
            />
          </FormGroup>

          <Button type="submit">Nachricht senden</Button>
        </Form>

        <div style={{ textAlign: 'center', marginTop: '2rem' }}>
          <BackButton type="button" onClick={handleGoBack}>
            Zurück
          </BackButton>
        </div>
      </FormCard>
    </Container>
  );
}

export default ContactForm;