// src/pages/FacilityDetail.js
import React, { useState, useEffect } from 'react';
import { useParams, Link } from 'react-router-dom';
import styled from 'styled-components';

const Container = styled.div`
  max-width: 1000px;
  margin: 3rem auto;
  padding: 2rem;
`;

const BackButton = styled(Link)`
  display: inline-block;
  margin-bottom: 2rem;
  color: #3498db;
  text-decoration: none;
  font-weight: 500;
  &:hover { text-decoration: underline; }
`;

const Card = styled.div`
  background: white;
  padding: 3rem;
  border-radius: 15px;
  box-shadow: 0 10px 30px rgba(0,0,0,0.1);
`;

const Name = styled.h1`
  color: #2c3e50;
  font-size: 2.5rem;
  margin-bottom: 1rem;
`;

const Address = styled.p`
  color: #7f8c8d;
  font-size: 1.3rem;
  margin-bottom: 2rem;
`;

const DetailGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
  margin-top: 2rem;
`;

const DetailBox = styled.div`
  background: #f8f9fa;
  padding: 1.5rem;
  border-radius: 10px;
  border-left: 5px solid #27ae60;
`;

const Label = styled.h3`
  color: #2c3e50;
  margin: 0 0 0.5rem 0;
  font-size: 1.1rem;
`;

const Value = styled.p`
  color: #34495e;
  font-size: 1.4rem;
  font-weight: 600;
  margin: 0;
`;

function FacilityDetail() {
  const { id } = useParams(); // ye /einrichtung/5 se 5 nikalta hai
  const [facility, setFacility] = useState(null);

  useEffect(() => {
    const facilities = JSON.parse(localStorage.getItem('facilities') || '[]');
    const found = facilities.find(f => f.id === parseInt(id));
    setFacility(found);
  }, [id]);

  if (!facility) {
    return (
      <Container>
        <h2>Einrichtung nicht gefunden</h2>
        <BackButton to="/suche">← Zurück zur Suche</BackButton>
      </Container>
    );
  }

  return (
    <Container>
      <BackButton to="/suche">← Zurück zur Suche</BackButton>

      <Card>
        <Name>{facility.name}</Name>
        <Address>{facility.address}</Address>

        <DetailGrid>
          <DetailBox>
            <Label>Pflegestufen</Label>
            <Value>{facility.careLevel}</Value>
          </DetailBox>

          <DetailBox>
            <Label>Zimmerarten</Label>
            <Value>{facility.roomType}</Value>
          </DetailBox>

          <DetailBox>
            <Label>Verfügbarkeit</Label>
            <Value>{facility.availability === 'sofort' ? 'Sofort verfügbar' : 'Kurzfristig verfügbar'}</Value>
          </DetailBox>

          <DetailBox>
            <Label>Preis pro Monat</Label>
            <Value>{facility.price}</Value>
          </DetailBox>
        </DetailGrid>

        <div style={{ marginTop: '3rem', textAlign: 'center' }}>
          <button style={{
            background: '#e67e22',
            color: 'white',
            padding: '1rem 3rem',
            border: 'none',
            borderRadius: '10px',
            fontSize: '1.3rem',
            fontWeight: '600',
            cursor: 'pointer'
          }}>
            Jetzt Kontakt aufnehmen
          </button>
        </div>
      </Card>
    </Container>
  );
}

export default FacilityDetail;