import React, { useEffect, useState } from "react";
import {
  StatsContainer,
  StatCard,
  StatNumber,
  StatLabel,
} from "./StyledComponents";
import styled from "styled-components";
import axios from "axios";
import { BaseUrl } from "../../BaseUrl";
 // ✅ correct import

// ===== Styled Components =====
const SectionContainer = styled.div`
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
`;

const NursingHomeHeader = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
  background: white;
  border-radius: 12px;
  padding: 1rem 1.5rem;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
`;

const AvatarCircle = styled.div`
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  color: white;
  font-size: 1.8rem;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 55px;
  height: 55px;
  border-radius: 50%;
`;

const HeaderTitle = styled.h2`
  margin: 0;
  font-size: 1.2rem;
  color: #2c3e50;
  font-weight: 600;
`;

const Divider = styled.hr`
  border: none;
  border-top: 1px solid #eaeaea;
  margin: 1rem 0;
`;

const FormContainer = styled.div`
  background: white;
  border-radius: 16px;
  padding: 2rem 2.5rem;
  width: 400px;
  margin: 0;
  box-shadow: 0 5px 15px rgba(0, 0, 0, 0.08);
`;

const FormTitle = styled.h3`
  margin-bottom: 1.2rem;
  font-size: 1.1rem;
  font-weight: 600;
  color: #2c3e50;
`;

const FormGroup = styled.div`
  display: flex;
  flex-direction: column;
  margin-bottom: 1rem;
`;

const Label = styled.label`
  font-size: 0.9rem;
  font-weight: 500;
  color: #34495e;
  margin-bottom: 0.4rem;
`;

const Input = styled.input`
  padding: 0.6rem 0.75rem;
  font-size: 0.9rem;
  border: 1.5px solid #dcdde1;
  border-radius: 8px;
  background: #f9f9f9;
  &:focus {
    outline: none;
    border-color: #2980b9;
    background: white;
  }
`;

const Button = styled.button`
  width: 100%;
  background-color: #3498db;
  color: white;
  font-weight: 600;
  font-size: 0.95rem;
  border: none;
  border-radius: 8px;
  padding: 0.7rem;
  margin-top: 0.5rem;
  cursor: pointer;
  transition: all 0.3s ease;
  &:hover {
    background-color: #2980b9;
  }
`;

// ===== Component =====
const ProfileSection = ({ userData, userName, spots = [] }) => {
  const [editData, setEditData] = useState({
    username: "",
    email: "",
    password: "",
  });
  const [loading, setLoading] = useState(false);

  const token = localStorage.getItem("pflegeUserToken");
  const userId = localStorage.getItem("pflegeUserId");

  // ✅ Fetch Profile Data
  useEffect(() => {
    const fetchProfile = async () => {
      if (!userId || !token) return;
      setLoading(true);
      try {
        const response = await axios.get(`${BaseUrl}get-profile`, {
          params: { user_id: userId },
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        });

        console.log("Profile Response:", response.data);

        // ✅ Handle API variations
        const user =
          response.data?.data ||
          response.data?.user ||
          response.data ||
          null;

        if (user) {
          setEditData({
            username: user.name || "",
            email: user.email || "",
            password: "",
          });
        } else {
          console.warn("⚠️ No profile data found:", response.data);
        }
      } catch (error) {
        console.error("❌ Profile fetch failed:", error.response?.data || error);
      } finally {
        setLoading(false);
      }
    };

    fetchProfile();
  }, [userId, token]);

  // ✅ Update Profile
  const handleSaveProfile = async (e) => {
    e.preventDefault();
    if (!userId) {
      alert("Kein Benutzer angemeldet!");
      return;
    }

    try {
      setLoading(true);
      const response = await axios.put(
        `${BaseUrl}update-profile`,
        {
          user_id: userId,
          name: editData.username,
          email: editData.email,
          password: editData.password || undefined,
        },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            Accept: "application/json",
            "Content-Type": "application/json",
          },
        }
      );

      console.log("Update Response:", response.data);

      if (response.data?.success || response.data?.status) {
        alert("Profil erfolgreich aktualisiert!");
      } else {
        alert(response.data?.message || "Aktualisierung fehlgeschlagen!");
      }
    } catch (error) {
      console.error("❌ Fehler beim Aktualisieren:", error.response?.data || error);
      alert("Serverfehler beim Aktualisieren des Profils!");
    } finally {
      setLoading(false);
    }
  };

  // ✅ Safe guard for spots
  const totalSpots = Array.isArray(spots) ? spots.length : 0;
  const sofortSpots = Array.isArray(spots)
    ? spots.filter((s) => s.availability?.toLowerCase() === "sofort").length
    : 0;
  const kurzfristigSpots = Array.isArray(spots)
    ? spots.filter((s) => s.availability?.toLowerCase() === "kurzfristig").length
    : 0;

  return (
    <SectionContainer>
      {/* === Dashboard Stats === */}
      <StatsContainer>
        <StatCard>
          <StatNumber>{totalSpots}</StatNumber>
          <StatLabel>Registrierte Plätze</StatLabel>
        </StatCard>
        <StatCard>
          <StatNumber>{sofortSpots}</StatNumber>
          <StatLabel>Sofort verfügbar</StatLabel>
        </StatCard>
        <StatCard>
          <StatNumber>{kurzfristigSpots}</StatNumber>
          <StatLabel>Kurzfristig verfügbar</StatLabel>
        </StatCard>
      </StatsContainer>

      {/* === Header Card === */}
      <NursingHomeHeader>
        <AvatarCircle>🏥</AvatarCircle>
        <HeaderTitle>{userName || "Ihr Pflegeheim"}</HeaderTitle>
      </NursingHomeHeader>

      <Divider />

      {/* === Edit Form === */}
      <FormContainer>
        <FormTitle>Anmeldedaten bearbeiten</FormTitle>
        <form onSubmit={handleSaveProfile}>
          <FormGroup>
            <Label>Name</Label>
            <Input
              type="text"
              value={editData.username}
              onChange={(e) =>
                setEditData({ ...editData, username: e.target.value })
              }
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>Email</Label>
            <Input
              type="email"
              value={editData.email}
              onChange={(e) =>
                setEditData({ ...editData, email: e.target.value })
              }
              required
            />
          </FormGroup>

          <FormGroup>
            <Label>Neues Passwort</Label>
            <Input
              type="password"
              value={editData.password}
              onChange={(e) =>
                setEditData({ ...editData, password: e.target.value })
              }
            />
          </FormGroup>

          <Button type="submit" disabled={loading}>
            {loading ? "Bitte warten..." : "Aktualisieren"}
          </Button>
        </form>
      </FormContainer>
    </SectionContainer>
  );
};

export default ProfileSection;
