import React, { useState, useEffect } from 'react';
import styled from 'styled-components';

// ====================== STYLES ======================
const Container = styled.div`
  max-width: 1300px;
  margin: 2rem auto;
  padding: 0 1rem;
`;

const SearchHeader = styled.div`
  text-align: center;
  margin-bottom: 2rem;
`;

const Title = styled.h1`
  color: #2c3e50;
  font-size: 2.2rem;
  margin-bottom: 0.5rem;
`;

const Subtitle = styled.p`
  color: #7f8c8d;
  font-size: 1.1rem;
`;

const Form = styled.form`
  background: white;
  padding: 1.5rem;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  margin-bottom: 2rem;
`;

const Row = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.9rem;
  margin-bottom: 1rem;
`;

const Label = styled.label`
  display: block;
  margin-bottom: 0.4rem;
  color: #34495e;
  font-size: 0.92rem;
  font-weight: 500;
`;

const Input = styled.input`
  width: 100%;
  padding: 0.7rem;
  border: 2px solid gray;
  border-radius: 7px;
  font-size: 0.95rem;
  &:focus { outline: none; border-color: gray; }
`;

const Select = styled.select`
  width: 100%;
  padding: 0.7rem;
  border: 2px solid gray;
  border-radius: 7px;
  font-size: 0.95rem;
  &:focus { outline: none; border-color: gray; }
`;

const SearchBtn = styled.button`
  background: #3498db;
  color: white;
  padding: 0.75rem 2rem;
  border: none;
  border-radius: 7px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  margin: 0.8rem auto 0;
  display: block;
  &:hover { background: #2980b9; }
`;

const ResultsGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1.8rem;
  margin-top: 2rem;

  @media (min-width: 1024px) {
    grid-template-columns: repeat(3, 1fr);
  }
`;

const Card = styled.div`
  background: white;
  padding: 1.6rem;
  border-radius: 12px;
  box-shadow: 0 4px 15px rgba(0,0,0,0.08);
  transition: all 0.3s;
  display: flex;
  flex-direction: column;
  height: 100%;
  &:hover { transform: translateY(-6px); box-shadow: 0 12px 25px rgba(0,0,0,0.12); }
`;

const Name = styled.h3`
  font-size: 1.22rem;
  color: #2c3e50;
  margin: 0 0 0.5rem 0;
  flex-grow: 1;
`;

const Address = styled.p`
  font-size: 0.88rem;
  color: #7f8c8d;
  margin: 0.5rem 0 1rem;
  line-height: 1.4;
`;

const Details = styled.div`
  font-size: 0.88rem;
  margin-bottom: 1.2rem;
  flex-grow: 1;
`;

const Detail = styled.div`
  display: flex;
  justify-content: space-between;
  margin: 0.45rem 0;
`;

const ButtonContainer = styled.div`
  margin-top: auto;
  padding-top: 0.8rem;
`;

const DetailsBtn = styled.button`
  background: #27ae60;
  color: white;
  border: none;
  padding: 0.75rem;
  border-radius: 7px;
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  width: 100%;
  &:hover { background: #219653; }
`;

/* ====================== DETAIL PAGE (NEW UI) ====================== */
const BackButton = styled.button`
  background: none;
  border: none;
  color: #2c3e50;
  font-size: 1rem;
  cursor: pointer;
  margin-bottom: 1rem;
  opacity: 0.8;
  &:hover { text-decoration: underline; opacity: 1; }
`;

const HeaderCard = styled.div`
  background: #ffffff;
  padding: 1.8rem;
  border-radius: 14px;
  box-shadow: 0 6px 22px rgba(0,0,0,0.08);
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1.2rem;
`;

const HeaderTitle = styled.h1`
  color: #23384a;
  font-size: 2rem;
  margin: 0;
`;

const HeaderSub = styled.p`
  color: #6b7b86;
  margin: 0;
  font-size: 1rem;
`;

const HeaderActions = styled.div`
  display: flex;
  gap: 0.8rem;
  flex-wrap: wrap;
`;

const PrimaryBtn = styled.button`
  background: #e74c3c;
  color: #fff;
  border: none;
  padding: 0.75rem 1.2rem;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  &:hover { background: #d84332; }
`;

const GhostBtn = styled.button`
  background: #7f9b9a;
  color: #fff;
  border: none;
  padding: 0.75rem 1.2rem;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  &:hover { filter: brightness(0.95); }
`;

const DetailGrid = styled.div`
  display: grid;
  grid-template-columns: 1fr;
  gap: 1rem;
  margin-top: 0.8rem;

  @media (min-width: 960px) {
    grid-template-columns: 1fr 1fr;
  }
`;

const InfoCard = styled.div`
  background: #ffffff;
  border-radius: 14px;
  box-shadow: 0 6px 22px rgba(0,0,0,0.08);
  padding: 1.2rem 1.4rem;
`;

const SectionTitle = styled.h3`
  color: #23384a;
  font-size: 1.2rem;
  margin: 0 0 0.8rem 0;
`;

const KV = styled.div`
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 0.6rem;
  padding: 0.9rem 0;
  border-bottom: 1px solid #e8eef2;

  &:last-child { border-bottom: none; }
`;

const Key = styled.span`
  color: #6b7b86;
`;

const Value = styled.span`
  color: #23384a;
  font-weight: 600;
`;

const ContactBox = styled.div`
  background: #f4f7f9;
  border: 1px solid #e1e8ee;
  border-radius: 10px;
  padding: 0.9rem 1rem;
  display: grid;
  gap: 0.6rem;
`;

const ContactRow = styled.div`
  display: flex;
  align-items: center;
  gap: 0.6rem;
  color: #23384a;
  font-size: 0.95rem;
`;

const AboutCard = styled(InfoCard)`
  grid-column: 1 / -1;
`;

const Bullet = styled.li`
  margin: 0.25rem 0;
  color: #23384a;
`;

/* Contact form styles (embedded in right info card) */
const SuccessAlert = styled.div`
  background: #d4edda;
  border: 1px solid #c3e6cb;
  color: #155724;
  padding: 0.9rem 1rem;
  border-radius: 8px;
  margin-bottom: 0.8rem;
`;

const FormField = styled.input`
  width: 100%;
  padding: 0.85rem;
  border-radius: 10px;
  border: 1px solid #ccd8e0;
  margin: 0.35rem 0 0.8rem;
  font-size: 0.95rem;
  &:focus { outline: none; border-color: #9fb6c4; }
`;

const TextArea = styled.textarea`
  width: 100%;
  padding: 0.85rem;
  border-radius: 10px;
  border: 1px solid #ccd8e0;
  margin: 0.35rem 0 0.8rem;
  min-height: 110px;
  font-size: 0.95rem;
  resize: vertical;
  &:focus { outline: none; border-color: #9fb6c4; }
`;

const SubmitBtn = styled.button`
  background: #e67e22;
  color: #fff;
  border: none;
  padding: 0.85rem 1.2rem;
  border-radius: 10px;
  font-weight: 600;
  cursor: pointer;
  &:hover { background: #d06f17; }
`;

// ================================================

export default function SearchPage() {
  const [view, setView] = useState('search');
  const [selectedFacility, setSelectedFacility] = useState(null);
  const [results, setResults] = useState([]);
  const [filters, setFilters] = useState({
    postalCode: '',
    city: '',
    distance: '',
    careLevel: '',
    roomType: '',
    availability: ''
  });

  const [showContact, setShowContact] = useState(false);
  const [contact, setContact] = useState({ name: '', phone: '', msg: '' });

  // ⭐ SUCCESS MESSAGE STATE (Added)
  const [successMsg, setSuccessMsg] = useState("");

  const facilities = [
    { id: 1, name: "St. Josef Pflegeheim", address: "Josefstraße 12, 53111 Bonn", city: "Bonn", careLevel: "1-5", roomType: "Einzel & Doppel", availability: "sofort", price: "ab 3.200 €" },
    { id: 2, name: "Seniorenresidenz Am Park", address: "Parkweg 8, 50933 Köln", city: "Köln", careLevel: "2-5", roomType: "Einzelzimmer", availability: "sofort", price: "ab 3.500 €" },
    { id: 3, name: "Haus Sonnenblick", address: "Sonnenallee 15, 40227 Düsseldorf", city: "Düsseldorf", careLevel: "1-4", roomType: "Einzel & Doppel", availability: "kurzfristig", price: "ab 3.800 €" },
    { id: 4, name: "Caritas Pflegeheim St. Maria", address: "Marienplatz 5, 80331 München", city: "München", careLevel: "1-5", roomType: "Einzelzimmer", availability: "sofort", price: "ab 4.100 €" },
    { id: 5, name: "AWO Seniorenzentrum Berlin", address: "Alexanderstraße 7, 10178 Berlin", city: "Berlin", careLevel: "3-5", roomType: "Doppelzimmer", availability: "kurzfristig", price: "ab 3.000 €" },
    { id: 6, name: "Haus Harvestehude Hamburg", address: "Harvestehuder Weg 20, 20148 Hamburg", city: "Hamburg", careLevel: "1-4", roomType: "Einzelzimmer", availability: "sofort", price: "ab 4.300 €" },
    { id: 7, name: "Pflegeheim St. Elisabeth", address: "Elisabethstraße 10, 40217 Düsseldorf", city: "Düsseldorf", careLevel: "2-5", roomType: "Einzel & Doppel", availability: "sofort", price: "ab 3.600 €" },
    { id: 8, name: "Seniorenheim Westend Frankfurt", address: "Westendstraße 50, 60325 Frankfurt", city: "Frankfurt", careLevel: "1-5", roomType: "Einzelzimmer", availability: "kurzfristig", price: "ab 4.000 €" },
    { id: 9, name: "Pflegezentrum Leipzig Süd", address: "Karl-Liebknecht-Str. 120, 04275 Leipzig", city: "Leipzig", careLevel: "1-4", roomType: "Doppelzimmer", availability: "sofort", price: "ab 2.900 €" },
    { id: 10, name: "Haus am Strom Bremen", address: "Am Strom 15, 28195 Bremen", city: "Bremen", careLevel: "2-5", roomType: "Einzelzimmer", availability: "sofort", price: "ab 3.300 €" }
  ];

  useEffect(() => {
    setResults(facilities);
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    let filtered = facilities;

    if (filters.postalCode) filtered = filtered.filter(f => f.address.includes(filters.postalCode));
    if (filters.city) filtered = filtered.filter(f => f.city.toLowerCase().includes(filters.city.toLowerCase()));
    if (filters.careLevel) filtered = filtered.filter(f => f.careLevel.includes(filters.careLevel));
    if (filters.roomType) filtered = filtered.filter(f => f.roomType.includes(filters.roomType));
    if (filters.availability) filtered = filtered.filter(f => f.availability === filters.availability);

    setResults(filtered);
  };

  const openDetail = (fac) => {
    setSelectedFacility(fac);
    setView('detail');
    window.scrollTo(0, 0);
  };

  // ⭐ Updated sendContact (logic same)
  const sendContact = (e) => {
    e.preventDefault();

    if (!contact.name.trim() || !contact.phone.trim()) {
      return;
    }

    setSuccessMsg("Ihre Anfrage wurde erfolgreich übermittelt!");
    setContact({ name: '', phone: '', msg: '' });

    setTimeout(() => {
      setSuccessMsg("");
      setShowContact(false);
    }, 2500);
  };

  return (
    <Container>
      {view === 'search' && (
        <>
          <SearchHeader>
            <Title>Pflegeheim finden</Title>
            <Subtitle>Das passende Heim für Ihre Liebsten – schnell und einfach</Subtitle>
          </SearchHeader>

          <Form onSubmit={handleSearch}>
            <Row>
              <div><Label>PLZ</Label><Input placeholder="z.B. 53111" onChange={e => setFilters({...filters, postalCode: e.target.value})} /></div>
              <div><Label>Stadt</Label><Input placeholder="z.B. Bonn" onChange={e => setFilters({...filters, city: e.target.value})} /></div>
              <div><Label>Entfernung (km)</Label><Input type="number" placeholder="30" onChange={e => setFilters({...filters, distance: e.target.value})} /></div>
            </Row>
            <Row>
              <div><Label>Pflegestufe</Label><Select onChange={e => setFilters({...filters, careLevel: e.target.value})}>
                <option value="">Alle</option><option value="1">1</option><option value="2">2</option><option value="3">3</option><option value="4">4</option><option value="5">5</option>
              </Select></div>
              <div><Label>Zimmerart</Label><Select onChange={e => setFilters({...filters, roomType: e.target.value})}>
                <option value="">Alle</option><option value="Einzel">Einzel</option><option value="Doppel">Doppel</option>
              </Select></div>
              <div><Label>Verfügbarkeit</Label><Select onChange={e => setFilters({...filters, availability: e.target.value})}>
                <option value="">Alle</option><option value="sofort">Sofort</option><option value="kurzfristig">Kurzfristig</option>
              </Select></div>
            </Row>
            <SearchBtn type="submit">Suchen</SearchBtn>
          </Form>

          <h2 style={{color: '#2c3e50', margin: '1.5rem 0 1rem'}}>{results.length} Einrichtungen gefunden</h2>

          <ResultsGrid>
            {results.map(f => (
              <Card key={f.id}>
                <Name>{f.name}</Name>
                <Address>{f.address}</Address>
                <Details>
                  <Detail><span>Pflege</span><strong>{f.careLevel}</strong></Detail>
                  <Detail><span>Zimmer</span><strong>{f.roomType}</strong></Detail>
                  <Detail><span>Verfügbarkeit</span><strong>{f.availability === 'sofort' ? 'Sofort' : 'Bald'}</strong></Detail>
                  <Detail><span>Preis</span><strong>{f.price}</strong></Detail>
                </Details>
                <ButtonContainer>
                  <DetailsBtn onClick={() => openDetail(f)}>Details anzeigen</DetailsBtn>
                </ButtonContainer>
              </Card>
            ))}
          </ResultsGrid>
        </>
      )}

      {view === 'detail' && selectedFacility && (
        <>
          <BackButton onClick={() => setView('search')}>← Zurück zur Suche</BackButton>

          {/* Header card like screenshot */}
          <HeaderCard>
            <div>
              <HeaderTitle>{selectedFacility.name}</HeaderTitle>
              <HeaderSub>{selectedFacility.address}</HeaderSub>
            </div>
            <HeaderActions>
              <PrimaryBtn onClick={() => setShowContact(true)}>Jetzt kontaktieren</PrimaryBtn>
              <GhostBtn onClick={() => setView('search')}>Zurück zur Suche</GhostBtn>
            </HeaderActions>
          </HeaderCard>

          <DetailGrid>
            {/* Left: Available places */}
            <InfoCard>
              <SectionTitle>Verfügbare Plätze</SectionTitle>
              <KV><Key>Pflegestufe</Key><Value>{selectedFacility.careLevel}</Value></KV>
              <KV><Key>Zimmerart</Key><Value>{selectedFacility.roomType}</Value></KV>
              <KV><Key>Verfügbarkeit</Key><Value>{selectedFacility.availability === "sofort" ? "Sofort" : "Kurzfristig"}</Value></KV>
              <KV><Key>Preis pro Monat</Key><Value>{selectedFacility.price}</Value></KV>
            </InfoCard>

            {/* Right: Contact information + (toggle) contact form */}
            <InfoCard>
              <SectionTitle>Kontaktinformationen</SectionTitle>
              <ContactBox>
                <ContactRow>📞 <span>0251 654321</span></ContactRow>
                <ContactRow>✉️ <span>info@st-josef.de</span></ContactRow>
              </ContactBox>

              {showContact && (
                <div style={{ marginTop: '1rem' }}>
                  <SectionTitle style={{ marginBottom: '0.4rem' }}>Nachricht senden</SectionTitle>

                  {successMsg && <SuccessAlert>{successMsg}</SuccessAlert>}

                  <form onSubmit={sendContact}>
                    <FormField
                      placeholder="Name"
                      value={contact.name}
                      onChange={e => setContact({ ...contact, name: e.target.value })}
                      required
                    />
                    <FormField
                      placeholder="Telefon"
                      value={contact.phone}
                      onChange={e => setContact({ ...contact, phone: e.target.value })}
                      required
                    />
                    <TextArea
                      placeholder="Nachricht (optional)"
                      value={contact.msg}
                      onChange={e => setContact({ ...contact, msg: e.target.value })}
                    />
                    <SubmitBtn type="submit">Absenden</SubmitBtn>
                    {' '}
                    <GhostBtn type="button" onClick={() => setShowContact(false)}>Schließen</GhostBtn>
                  </form>
                </div>
              )}
            </InfoCard>

            {/* Bottom: About section (static text placeholder like screenshot) */}
            <AboutCard>
              <SectionTitle>Über die Einrichtung</SectionTitle>
              <p style={{ color: '#6b7b86', marginTop: 0 }}>
                Traditionelle Pflegeeinrichtung mit familiärer Atmosphäre.
              </p>
              <div>
                <p style={{ color: '#23384a', fontWeight: 600, marginBottom: '0.4rem' }}>Services:</p>
                <ul style={{ paddingLeft: '1.2rem', margin: 0 }}>
                  <Bullet>Vollstationäre Pflege</Bullet>
                  <Bullet>Demenzbetreuung</Bullet>
                  <Bullet>Kurzzeitpflege</Bullet>
                  <Bullet>Tagespflege</Bullet>
                </ul>
              </div>
            </AboutCard>
          </DetailGrid>
        </>
      )}
    </Container>
  );
}
